import {
  type Slider as SliderController,
  type SliderOptions,
  createSlider,
} from "@cssints/headless";
import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };
import { merge, untrack } from "solid-js";

import { type PartProps, type Render, renderPart, type Renderable } from "./render.tsx";
import { t } from "./theme.ts" with { type: "cssints" };

/** What `render` gets: the rail's props, its class merged with the caller's, and `data-part`. */
export type SliderPartProps = PartProps;

export interface SliderProps extends Omit<SliderOptions, "id">, Renderable<SliderPartProps, void> {
  /** The slider's name: a `role="slider"` needs one. */
  readonly label: string;
  /** The thumb: `render` is the rail, which is the box a page lays out. */
  readonly renderThumb?: Render<PartProps, void>;
  readonly class?: string;
  /** The primitive, once: a page that reads the figure as well as shows it. */
  readonly onReady?: (slider: SliderController) => void;
}

// The rail is the box, the fill and the thumb are decoration over it: the thumb is the announced `role=slider`, and the
// primitive owns its value, bounds, orientation, keys and the drag. The rail copies the announced orientation to
// `data-orientation` because a box cannot read an attribute of its child: the fill and the thumb paint the vertical geometry
// from it, and the thumb paints its own from `aria-orientation` — one source, the primitive's `orientation`, so the two cannot
// disagree. `touch-action` and `user-select` are the one thing the drag needs from CSS (the primitive carries none): a press
// on a touch rail must move the thumb instead of scrolling the page, and a mouse drag must not select the text it crosses.
const rail = css.cn(
  css.boxSizing("border-box"),
  css.position("relative"),
  css.display("block"),
  css.width("100%"),
  css.height(t.space._2),
  css.bg(t.color.buttonBackground),
  css.borderRadius("999px"),
  css.cursor("pointer"),
  css.touchAction("none"),
  css.userSelect("none"),
  css.transition("background-color 120ms"),
  css.attr("data-orientation", "vertical")(css.width(t.space._2), css.height(t.space._10)),
  css.attr("aria-disabled", "true")(css.bg(t.color.borderDisabled), css.cursor("not-allowed")),
);

const fill = css.cn(
  css.position("absolute"),
  css.insetBlock("0"),
  css.insetInlineStart("0"),
  css.borderRadius("999px"),
  css.bg(t.color.highlight),
  css.transition("width 120ms, height 120ms"),
  css.within(css.attr("data-orientation", "vertical"))(
    css.insetBlock("auto"),
    css.insetBlockEnd("0"),
    css.height("100%"),
    css.width("100%"),
  ),
  css.attr("aria-disabled", "true")(css.bg(t.color.textDisabled)),
);

const thumb = css.cn(
  css.boxSizing("border-box"),
  css.position("absolute"),
  css.insetBlockStart("50%"),
  css.width("1.25rem"),
  css.height("1.25rem"),
  css.border("1px solid", t.color.border),
  css.borderRadius("999px"),
  css.bg(t.color.surface),
  css.transform("translate(-50%, -50%)"),
  css.transition("background-color 120ms, border-color 120ms"),
  css.hover(css.border("1px solid", t.color.borderHover)),
  css.focusVisible(css.outline("2px solid", t.color.focusRing), css.outlineOffset("2px")),
  css.attr("aria-disabled", "true")(
    css.bg(t.color.borderDisabled),
    css.border("1px solid", t.color.borderDisabled),
    css.cursor("not-allowed"),
  ),
  css.attr("aria-orientation", "vertical")(
    css.insetBlockStart("auto"),
    css.transform("translate(-50%, 50%)"),
  ),
);

/**
 * APG slider, styled: a rail, the fill of the value and the thumb. `createSlider` owns the value, the bounds, the
 * orientation, the arrow/Home/End keys, the rail press and the drag; the one thing CSS cannot read off `aria-valuenow` is the
 * fill's share of the rail (an arithmetic turn of `attr()` inside `calc()`), so the width is an inline percentage of the same
 * attributes the thumb announces, as `Meter` does. Vertical, the rail is as tall as `space.10` and a page sets its own.
 *
 * `value` makes it controlled; without it the slider owns the value. `onValueChange` is a request the host may ignore.
 * `disabled` is the primitive's: it announces `aria-disabled` on the thumb and drops every key, rail press and drag, so the
 * kit only copies that announced state onto the rail and the fill (a box cannot read an attribute of its child).
 */
export const Slider = (props: SliderProps): JSX.Element => {
  const slider = createSlider({
    get min() {
      return props.min;
    },
    get max() {
      return props.max;
    },
    get step() {
      return props.step;
    },
    get largeStep() {
      return props.largeStep;
    },
    get value() {
      return props.value;
    },
    defaultValue: props.defaultValue,
    get orientation() {
      return props.orientation;
    },
    get direction() {
      return props.direction;
    },
    get disabled() {
      return props.disabled;
    },
    get onValueChange() {
      return props.onValueChange;
    },
  });
  untrack(() => props.onReady)?.(slider);

  const orientation = (): "horizontal" | "vertical" => props.orientation ?? "horizontal";
  // the same two attributes the thumb announces, so the fill cannot disagree with the value a reader hears
  const percent = (): number => {
    const min = Number(slider.thumbProps["aria-valuemin"]);
    const max = Number(slider.thumbProps["aria-valuemax"]);
    const now = Number(slider.thumbProps["aria-valuenow"]);
    return max > min ? ((now - min) / (max - min)) * 100 : 0;
  };

  const railPart = merge(slider.trackProps, {
    "data-part": "slider",
    get "data-orientation"() {
      return slider.thumbProps["aria-orientation"];
    },
    get "aria-disabled"() {
      return slider.thumbProps["aria-disabled"];
    },
    get class() {
      return css.cn(rail, props.class);
    },
  });

  const thumbPart = merge(slider.thumbProps, {
    "data-part": "slider-thumb",
    "aria-label": props.label,
    class: thumb,
    get style() {
      return orientation() === "vertical"
        ? { "inset-inline-start": "50%", "inset-block-end": `${percent()}%` }
        : { "inset-inline-start": `${percent()}%` };
    },
  });

  return renderPart(props, railPart, undefined, (part) => (
    <div {...part}>
      <span
        aria-hidden="true"
        data-part="slider-fill"
        class={fill}
        style={
          orientation() === "vertical" ? { height: `${percent()}%` } : { width: `${percent()}%` }
        }
      />
      {renderPart({ render: props.renderThumb }, thumbPart, undefined, (control) => (
        <div {...control} />
      ))}
    </div>
  ));
};

import type { JSX } from "@solidjs/web";
import { untrack } from "solid-js";

/**
 * What a part hands to `render`: the props the part owns (`id`, `aria-*`, `data-part`, `class`) and the state it is in, as
 * accessors — Solid does not re-render a component, so a snapshot would be dead on the second read.
 *
 * Base UI's `render` takes an element and clones it with the part's props; Solid cannot clone (JSX is already a node), so
 * the element form becomes the function form and a component is that function: `render={(props) => <a {...props} />}`,
 * `render={Button}`.
 */
export type Render<P extends object, S> = (props: P, state: S) => JSX.Element;

/**
 * What a part hands to `render`: element-generic attributes, because the element is the caller's (`<a>`, `<textarea>`, a
 * component). `ref` stays the caller's too — a part cannot type a ref for an element it has not chosen.
 */
export type PartProps = Omit<JSX.HTMLAttributes<HTMLElement>, "ref"> & {
  readonly class?: string;
};

/** A part that anything can render: `render` replaces its element and keeps the props the part owns. */
export interface Renderable<P extends object, S> {
  readonly render?: Render<P, S> | undefined;
}

/**
 * Renders a part: the caller's `render` when it gave one, the part's own element otherwise. `render` is structural, so it is
 * read once (untracked): a part that swapped it at run time would need a remount, not an update.
 *
 * @param {Renderable<P, S>} part the component's props, for the `render` it may carry
 * @param {P} props the part's props, already merged with the caller's own and with `class` and `data-part`
 * @param {S} state the part's state, as accessors
 * @param {(props: P) => JSX.Element} fallback the element the part is by default
 * @returns {JSX.Element} the part
 */
export const renderPart = <P extends object, S>(
  part: Renderable<PartProps, S>,
  props: P,
  state: S,
  fallback: (props: P) => JSX.Element,
): JSX.Element => {
  const render = untrack(() => part.render);
  // the part hands more than `PartProps` (its own element's attributes: `type` on a button, `value` on an input); a render
  // function is typed by what every part guarantees, and reads the rest as the DOM attributes they are
  return render === undefined ? fallback(props) : render(props as PartProps, state);
};

import { look } from "@cssints/mise-en-mode" with { type: "cssints" };
import { check, createGlobalTheme, createTokens, media } from "cssints" with { type: "cssints" };

import { darkTheme, forcedColorsTheme, lightTokens } from "./tokens.ts";

// The theme the starters are written against: one lightness scale, one hue and one chroma per
// colour family, and the semantic colours made of them. The data lives in tokens.ts, so the
// registry can compile it to a plain theme.css without the cssints plugin; this module is the
// same theme for the components and the demo page, with the contrast gate.
const t = createTokens(lightTokens);

// The dark mode is the lightness scale turned over, so every step and every colour made of it follows: the text is still
// gray-1200, it is just a light gray now. The page and the surface are the reference's own dark values, and the popover shadow
// deepens because a shadow on a dark page reads as a smudge.
createGlobalTheme(t, media("(prefers-color-scheme: dark)"), darkTheme);

// The same dark look as a scope a page can ask for: `<div data-mode="dark">` moves every token inside it, and a surface or a
// frame under it follows without a prop. It is a mise-en-mode look, so it is in the `app` layer: a host's `author` or `viewer`
// look over the same marker wins without a specificity trick, and `data-mode="dark/color"` moves the colours alone. The media
// query above stays a global theme: a look is a `data-mode` scope, and the system preference is not one.
look(t, "dark", "app", darkTheme);

// One preset, because the theme is neutral: the reference's indigo, as its two numbers. The others are in its theme.css.
createGlobalTheme(t, '[data-tint="indigo"]', {
  hue: { tint: "284.23" },
  chroma: { tint: "0.25049" },
});

// On a dense screen (200dpi and up) the targets grow: the spacing steps and the text with them, as in the reference.
createGlobalTheme(t, media("(min-resolution: 200dpi)"), {
  space: { base: "calc(0.25rem * 1.25)" },
  font: { sizeSm: "0.9375rem", size: "1.0625rem", sizeLg: "1.25rem" },
});

// Windows high contrast mode throws the theme away and paints the system's own colours; forced-colors makes that explicit,
// since a component that reads a token here gets the system colour rather than the tint.
createGlobalTheme(t, media("(forced-colors: active)"), forcedColorsTheme);

// The pairs a reader meets on every page: body text, the second level of text, and a link on a card. Both modes and every
// theme above are checked (the preset too, since it sets the tokens the link is made of), and a ratio under the floor fails
// the build. 7 for text and 4.5 for the rest are the WCAG 2.x AAA and AA floors.
check.contrast(t.color.text, t.color.page, { min: 7 }); // the tabs skin's selected label
check.contrast(t.color.muted, t.color.page, { min: 4.5 }); // its unselected label
check.contrast(t.color.link, t.color.surface, { min: 4.5 });
check.contrast(t.color.placeholder, t.color.page, { min: 4.5 });
check.contrast(t.color.onHighlight, t.color.highlight, { min: 4.5 });
// The active tab's underline is a graphic against the page: 3 is the WCAG 1.4.11 floor for non-text contrast. The dark
// mode is the closest (3.55:1 without the preset, 3.17:1 with indigo), so a lighter highlight would break it.
check.contrast(t.color.highlight, t.color.page, { min: 3 });
// The focus ring is a graphic, not text: 3 is the WCAG 1.4.11 floor for a non-text contrast.
check.contrast(t.color.focusRing, t.color.page, { min: 3 }); // the tabs skin's ring

export { t };

import { type Slider as SliderController } from "@cssints/headless";
import type { SliderConfig } from "@cssints/apg-specs/apg/slider.bridge";
import type { Json } from "@cssints/apg-specs/scenario";
import type { Mounted } from "./slider-driver.ts";
import { Slider as StyledSlider } from "./slider.tsx";
import { createSignal } from "solid-js";
import { render } from "@solidjs/web";

/**
 * Mounts the styled slider for the scenario walk and exposes what the driver needs: the
 * `data-part="slider-thumb"` element, the callback payloads, and a way to push a programmatic
 * change. `orientation` / `direction` live in signals so a `prop` step can flip them; a `pointer`
 * prop is a rail press at a 0..1 fraction (it focuses the thumb, as a user's press would).
 * Controlled, the fixture is the host: it keeps the value in a signal, passes it as `value`, and
 * either writes every request back (`accepts`) or ignores the callback.
 */
export const mountSlider = (config: SliderConfig): Mounted => {
  const root = document.createElement("div");
  document.body.append(root);
  const events = new Map<string, Json[]>();
  const push = (name: string, payload: Json): void => {
    events.set(name, [...(events.get(name) ?? []), payload]);
  };
  const [orientation, setOrientation] = createSignal(config.orientation);
  const [direction, setDirection] = createSignal(config.dir);
  const [host, setHost] = createSignal(config.value);
  const writeHost = (next: number): void => {
    if (config.controlled) {
      setHost(next);
    }
  };
  let api: SliderController | undefined;

  const dispose = render(() => {
    return (
      <StyledSlider
        label="Value"
        min={config.min}
        max={config.max}
        step={config.step}
        largeStep={config.largeStep}
        defaultValue={config.value}
        value={config.controlled ? host() : undefined}
        orientation={orientation()}
        direction={direction()}
        onReady={(controller) => {
          api = controller;
        }}
        onValueChange={(value) => {
          push("onValueChange", value);
          if (config.accepts) {
            setHost(value);
          }
        }}
      />
    );
  }, root);

  const thumb = (): HTMLElement | null =>
    root.querySelector<HTMLElement>('[data-part="slider-thumb"]');

  return {
    root,
    events,
    value: () => api?.value() ?? config.value,
    setProp: (name, value) => {
      switch (name) {
        case "orientation":
          setOrientation(value === "vertical" ? "vertical" : "horizontal");
          break;
        case "dir":
        case "direction":
          setDirection(value === "rtl" ? "rtl" : "ltr");
          break;
        case "pointer":
          api?.pointerDown(Number(value));
          thumb()?.focus();
          break;
        case "setValue":
          writeHost(Number(value));
          break;
        case "hostToggle":
          writeHost(host() === config.max ? config.min : config.max);
          break;
        case "focus":
          api?.focus();
          thumb()?.focus();
          break;
        case "blur":
          api?.blur();
          thumb()?.blur();
          break;
        default:
          throw new Error(`slider fixture has no prop ${name}`);
      }
    },
    focus: () => (api?.focused() === true ? "thumb" : null),
    dispose: () => {
      dispose();
      root.remove();
    },
  };
};

import { type ActionStep, type Driver, type Json, Unsupported } from "@cssints/apg-specs/scenario";
import { flush } from "solid-js";
import { userEvent } from "vite-plus/test/browser";

/**
 * The generic DOM side of the scenario bridge. A pattern's fixture renders its
 * parts with `data-part="<name>"` and returns a `Mounted`; this turns scenario
 * steps into real pointer/keyboard input and DOM reads into observations.
 */
export interface Mounted {
  readonly root: HTMLElement;
  /** Apply a scenario `prop` step (programmatic input) to the mounted widget. */
  readonly setProp: (name: string, value: Json | undefined) => void;
  /** Callback payloads, recorded under their canonical name. */
  readonly events: ReadonlyMap<string, ReadonlyArray<Json>>;
  readonly value?: () => Json;
  /**
   * The part the primitive itself considers focused (`trigger`, `tab:1`), or
   * `null`. Preferred over `document.activeElement` so the walk does not race the
   * fixtures' deferred DOM focus (bean 209r).
   */
  readonly focus?: () => string | null;
  readonly dispose: () => void;
}

export interface DomDriverOptions {
  /** Parts that can be hidden: the ones `expect.visible` lists. */
  readonly hideableParts: ReadonlyArray<string>;
  readonly eventName?: (name: string) => string;
}

const BOOLEAN_ATTRS = new Set(["hidden", "disabled"]);
const REFERENCE_ATTRS = new Set([
  "aria-controls",
  "aria-labelledby",
  "aria-owns",
  "aria-activedescendant",
]);
const NAMED_KEYS = new Set(["Enter", "Tab", "Escape", "Backspace", "Delete", "Home", "End"]);

// Solid renders on its own schedule, but `flush()` applies the queued signal work
// synchronously; the fixtures then move DOM focus in a `setTimeout(0)` macrotask
// (kept for user-event's Enter semantics). Waiting one macrotask lets both land
// before the walk reads, without a frame — a frame also lets the browser's focus
// fixup run and perturb the observation (bean 209r). The walk reads focus from
// the fixture's primitive state when it offers one (`Mounted.focus`).
const settle = (): Promise<void> => {
  flush();
  return new Promise((resolve) => {
    setTimeout(resolve, 0);
  });
};

const keyboardSyntax = (key: string): string => {
  if (key === "Space" || key === " ") {
    return " ";
  }
  return NAMED_KEYS.has(key) || key.startsWith("Arrow") || key.startsWith("Page")
    ? `{${key}}`
    : key;
};

// A held key is always written by name: `{Space>}` keeps it down, `{/Space}`
// releases it wherever focus is at that moment (a blur between the two halves
// is exactly what a walk needs to see).
const keyName = (key: string) => (key === " " || key === "Space" ? "Space" : key);

/** `KeyboardEvent.key` uses a space character, not the `Space` alias. */
const eventKey = (key: string) => (key === "Space" ? " " : key);

const CLICKABLE_INPUT_TYPES = new Set([
  "button",
  "color",
  "file",
  "image",
  "reset",
  "submit",
  "checkbox",
  "radio",
]);

/**
 * A half press is dispatched directly (not through user-event's held-key state,
 * which auto-releases on a repeated down and leaks across walk drivers). The
 * two native activations user-event would otherwise add are emulated: Space
 * clicks a button-like element on keyup, Enter on keydown.
 */
const halfPress = (target: EventTarget | null, type: "keydown" | "keyup", key: string) => {
  if (!(target instanceof HTMLElement)) {
    return;
  }
  const keyValue = eventKey(key);
  const notPrevented = target.dispatchEvent(
    new KeyboardEvent(type, {
      key: keyValue,
      code: keyName(key),
      bubbles: true,
      cancelable: true,
    }),
  );
  const clickable =
    target.tagName === "BUTTON" ||
    (target instanceof HTMLInputElement && CLICKABLE_INPUT_TYPES.has(target.type));
  if (
    notPrevented &&
    clickable &&
    ((type === "keyup" && keyValue === " ") || (type === "keydown" && keyValue === "Enter"))
  ) {
    target.click();
  }
};

export const domDriver = (mounted: Mounted, options: DomDriverOptions): Driver => {
  const { root } = mounted;
  const canonical = options.eventName ?? ((name: string) => name);

  const partsOf = (name: string): HTMLElement[] => [
    ...root.querySelectorAll<HTMLElement>(`[data-part="${name}"]`),
  ];

  const targetOf = (element: HTMLElement): string => {
    const name = element.dataset["part"] ?? "";
    return `${name}:${partsOf(name).indexOf(element)}`;
  };

  const elementOf = (target: string): HTMLElement => {
    const [name = "", index = "0"] = target.split(":");
    const element = partsOf(name)[Number(index)];
    if (element === undefined) {
      throw new Unsupported(`part ${target}`);
    }
    return element;
  };

  const click = async (element: HTMLElement): Promise<void> => {
    // a disabled button is not actionable; force lets the browser drop the click itself
    await userEvent.click(element, { force: true });
  };

  // Half presses this driver dispatched a keydown for, so a stray `phase: "up"`
  // stays inert (the spec's key_up only fires on an armed press).
  const halfHeld = new Set<string>();

  return {
    perform: async (step: ActionStep) => {
      switch (step.event) {
        case "focus":
          elementOf(step.target ?? "").focus();
          break;
        case "blur":
          halfHeld.clear();
          elementOf(step.target ?? "").blur();
          break;
        case "click":
          await click(elementOf(step.target ?? ""));
          break;
        case "pointerdown":
          elementOf(step.target ?? "").focus();
          elementOf(step.target ?? "").dispatchEvent(
            new PointerEvent("pointerdown", {
              bubbles: true,
              cancelable: true,
              pointerType: step.pointerType ?? "mouse",
            }),
          );
          break;
        case "pointerup": {
          const element = elementOf(step.target ?? "");
          element.dispatchEvent(
            new PointerEvent("pointerup", {
              bubbles: true,
              cancelable: true,
              pointerType: step.pointerType ?? "mouse",
            }),
          );
          // a released pointer button is a click, as the browser would deliver it
          element.click();
          break;
        }
        case "pointercancel":
          elementOf(step.target ?? "").dispatchEvent(
            new PointerEvent("pointercancel", {
              bubbles: true,
              cancelable: true,
              pointerType: step.pointerType ?? "mouse",
            }),
          );
          break;
        case "hover":
          await userEvent.hover(elementOf(step.target ?? ""));
          break;
        case "unhover":
          await userEvent.unhover(elementOf(step.target ?? ""));
          break;
        case "key": {
          if (step.phase === "down") {
            const element = elementOf(step.target ?? "");
            if (document.activeElement !== element) {
              element.focus();
            }
            // a disabled/read-only control never arms (the spec's spaceArms
            // guard), so a later `up` must not activate it either
            const blocked =
              element.getAttribute("aria-disabled") === "true" ||
              element.getAttribute("aria-readonly") === "true" ||
              (element instanceof HTMLButtonElement && element.disabled);
            if (!blocked) {
              halfHeld.add(keyName(step.key ?? ""));
            }
            halfPress(element, "keydown", step.key ?? "");
            break;
          }
          if (step.phase === "up") {
            if (!halfHeld.delete(keyName(step.key ?? ""))) {
              break;
            }
            // release wherever focus went: deliberately do NOT re-focus the
            // target, or a keydown -> blur -> keyup walk would be defeated
            const active = document.activeElement;
            halfPress(
              active instanceof HTMLElement ? active : document.body,
              "keyup",
              step.key ?? "",
            );
            break;
          }
          const element = elementOf(step.target ?? "");
          if (document.activeElement !== element) {
            element.focus();
          }
          // a whole press releases the key, so a later `phase: "up"` is inert
          halfHeld.delete(keyName(step.key ?? ""));
          await userEvent.keyboard(keyboardSyntax(step.key ?? ""));
          break;
        }
        case "prop":
          if (step.set !== undefined) {
            for (const [name, value] of Object.entries(step.set)) {
              mounted.setProp(name, value);
              if ((name === "disabled" || name === "isDisabled") && value === true) {
                // the spec drops a pending press when the control disables
                halfHeld.clear();
              }
            }
          } else {
            mounted.setProp(step.prop ?? "", step.value);
            if ((step.prop === "disabled" || step.prop === "isDisabled") && step.value === true) {
              halfHeld.clear();
            }
          }
          break;
        default:
          throw new Unsupported(`event ${step.event}`);
      }
      await settle();
    },
    observer: {
      focus: () => {
        // Prefer the primitive's own focus: the fixtures sync DOM focus in a
        // deferred macrotask (kept for user-event's Enter semantics), so reading
        // `document.activeElement` here races that (bean 209r).
        if (mounted.focus !== undefined) {
          return mounted.focus();
        }
        const active = document.activeElement;
        const part =
          active instanceof HTMLElement ? active.closest<HTMLElement>("[data-part]") : null;
        return part !== null && root.contains(part) ? targetOf(part) : null;
      },
      attr: (target, name) => {
        if (name.startsWith("data-")) {
          throw new Unsupported(`styling hook ${name}`);
        }
        const value = elementOf(target).getAttribute(name);
        if (value === null) {
          return null;
        }
        if (value === "" && BOOLEAN_ATTRS.has(name)) {
          return "true";
        }
        if (REFERENCE_ATTRS.has(name)) {
          const referenced = root.querySelector<HTMLElement>(`[id="${value}"]`);
          return referenced?.dataset["part"] === undefined ? value : targetOf(referenced);
        }
        return value;
      },
      visible: () =>
        options.hideableParts.flatMap((name) =>
          partsOf(name)
            .filter((element) => element.checkVisibility())
            .map(targetOf),
        ),
      events: (name) => mounted.events.get(canonical(name)) ?? [],
      ...(mounted.value === undefined ? {} : { value: mounted.value }),
    },
    dispose: mounted.dispose,
  };
};

import {
  type ScenarioConfig,
  ScenarioMismatch,
  differentialWalk,
  parseScenarioFile,
  replayScenario,
  specDriver,
} from "@cssints/apg-specs/scenario";
import {
  sliderBridge,
  sliderConfig,
  sliderProbe,
  sliderSteps,
} from "@cssints/apg-specs/apg/slider.bridge";
import { decodeDefinition, makeReferenceModel } from "@quint-machine/core";
import { createSignal } from "solid-js";
import { render } from "@solidjs/web";
import { describe, expect, it } from "vite-plus/test";
import baseUi from "@cssints/apg-specs/scenarios/apg/slider.base-ui.json";
import definitionJson from "@cssints/apg-specs/apg/slider.model.json";
import { domDriver } from "./slider-driver.ts";
import { mountSlider } from "./slider.fixture";
import reactAria from "@cssints/apg-specs/scenarios/apg/slider.react-aria.json";
import { Slider } from "./slider.tsx";
import type { Slider as SliderController, SliderOptions } from "@cssints/headless";

// The copy's own conformance: the same scenarios the primitive is checked against, driven through
// this styled slider rather than through the bare controller. The bridge speaks the primitive's
// parts (`thumb`, `track`); the skin names them after itself (`slider-thumb`, `slider`), so the
// target is translated on the way in and every attribute read lands on the skin's own element.
const model = makeReferenceModel(decodeDefinition(definitionJson));

// Solid 2 delivers events through its delegated listener on a later turn, and applies setters on its flush.
const tick = () => new Promise((resolve) => setTimeout(resolve, 20));

type Driver = ReturnType<typeof domDriver>;

const toSkin = (target: string | undefined): string | undefined =>
  target?.replace(/^thumb/, "slider-thumb").replace(/^(track|rail)/, "slider");

const translated = (driver: Driver): Driver => ({
  ...driver,
  perform: (step) => {
    const target = toSkin(step.target);
    return driver.perform(target === undefined ? step : { ...step, target });
  },
  observer: {
    ...driver.observer,
    attr: (target, name) => driver.observer.attr(toSkin(target) ?? target, name),
  },
});

const dom = (config: ScenarioConfig) =>
  translated(domDriver(mountSlider(sliderConfig(config)), { hideableParts: [] }));

// Scenarios whose expectations the primitive deliberately does not meet. Each
// entry must still fail (so closing the gap forces removing it) and says why.
// The spec fixes one configuration (range 0..10, step 1, value 5), so most
// ported scenarios are `Unsupported` rather than divergent.
const DIVERGENCES: Readonly<Record<string, string>> = {};

describe("Slider x ported scenarios (real DOM)", () => {
  for (const source of [baseUi, reactAria]) {
    const file = parseScenarioFile(source);
    describe(file.source, () => {
      for (const scenario of file.scenarios) {
        it(scenario.id, async (context) => {
          const run = replayScenario(scenario, sliderBridge, dom);
          const divergence = DIVERGENCES[scenario.id];
          if (divergence !== undefined) {
            await expect(run).rejects.toBeInstanceOf(ScenarioMismatch);
            return;
          }
          const result = await run;
          if (result.status === "unsupported") {
            context.skip(result.reason);
          }
        });
      }
    });
  }
});

describe("Slider x spec (differential walk)", () => {
  // uncontrolled, then a controlled host that accepts every request, one that
  // pins the value (rejects), and one that pins it while vertical. The step-2
  // variants (bean qtmy) make a walk notice an arrow key that ignores `step`.
  const CONFIGS: ReadonlyArray<ScenarioConfig> = [
    {},
    { orientation: "vertical" },
    { dir: "rtl" },
    { orientation: "vertical", dir: "rtl" },
    { step: 2, largeStep: 4 },
    { step: 2, largeStep: 4, dir: "rtl" },
    { controlled: true },
    { controlled: true, value: 5 },
    { controlled: true, orientation: "vertical" },
    { controlled: true, step: 2, largeStep: 4, value: 6 },
  ];
  for (const config of CONFIGS) {
    it(`matches the generated model for ${JSON.stringify(config)}`, async () => {
      await differentialWalk({
        alphabet: sliderSteps,
        probe: sliderProbe,
        makePair: () => Promise.resolve([specDriver(model, sliderBridge, config), dom(config)]),
        runs: 15,
        steps: 25,
        seed: 7,
      });
    });
  }
});

// The skin's own contract: the rail copies the announced orientation and the disabled state (a box
// cannot read an attribute of its child), and the fill is the value's share of the rail as an inline
// percentage of the same attributes the thumb announces.
const mount = (view: () => ReturnType<typeof Slider>): HTMLElement => {
  const root = document.createElement("div");
  document.body.append(root);
  render(view, root);
  return root;
};

const part = (root: HTMLElement, name: string): HTMLElement =>
  root.querySelector<HTMLElement>(`[data-part="${name}"]`)!;

describe("Slider skin", () => {
  it("paints the fill as the thumb's share, and copies its orientation onto the rail", async () => {
    const root = mount(() => <Slider label="Volume" defaultValue={5} />);
    const rail = part(root, "slider");
    const fill = part(root, "slider-fill");
    const thumb = part(root, "slider-thumb");
    expect(rail.getAttribute("data-orientation")).toBe("horizontal");
    expect(thumb.getAttribute("aria-orientation")).toBe("horizontal");
    expect(thumb.getAttribute("role")).toBe("slider");
    expect(thumb.getAttribute("aria-label")).toBe("Volume");
    expect(thumb.getAttribute("aria-valuenow")).toBe("5");
    expect(fill.getAttribute("aria-hidden")).toBe("true");
    expect(fill.style.width).toBe("50%");
    // a key moves the value and the fill follows the same attributes the thumb announces
    thumb.focus();
    await tick();
    thumb.dispatchEvent(new KeyboardEvent("keydown", { key: "ArrowRight", bubbles: true }));
    await tick();
    expect(thumb.getAttribute("aria-valuenow")).toBe("6");
    expect(fill.style.width).toBe("60%");
  });

  it("takes its geometry from the range, and vertical grows upward", () => {
    const root = mount(() => <Slider label="Volume" min={10} max={50} defaultValue={25} />);
    // 25 in 10..50 is three eighths of the rail
    expect(part(root, "slider-fill").style.width).toBe("37.5%");

    const vertical = mount(() => (
      <Slider label="Volume" min={10} max={50} defaultValue={25} orientation="vertical" />
    ));
    expect(part(vertical, "slider").getAttribute("data-orientation")).toBe("vertical");
    expect(part(vertical, "slider-thumb").getAttribute("aria-orientation")).toBe("vertical");
    const fill = part(vertical, "slider-fill");
    expect(fill.style.height).toBe("37.5%");
    expect(fill.style.width).toBe("");
  });

  it("copies aria-disabled onto the rail, so the rail and the thumb are greyed together", () => {
    const root = mount(() => <Slider label="Volume" defaultValue={5} disabled />);
    expect(part(root, "slider-thumb").getAttribute("aria-disabled")).toBe("true");
    expect(part(root, "slider").getAttribute("aria-disabled")).toBe("true");
    // painted from the attribute the rail now carries
    expect(getComputedStyle(part(root, "slider")).cursor).toBe("not-allowed");
    expect(getComputedStyle(part(root, "slider-thumb")).cursor).toBe("not-allowed");
  });
});

// `disabled` is a widget-level extension of the pattern (the spec omits it): the thumb
// keeps its tab stop, announces `aria-disabled`, and drops every key and rail press.
describe("Slider disabled", () => {
  const renderSlider = () => {
    const root = document.createElement("div");
    root.style.cssText = "position:fixed;top:0;left:0;width:100px;height:20px";
    document.body.append(root);
    const [disabled, setDisabled] = createSignal(true);
    let api: SliderController | undefined;
    const dispose = render(
      () => (
        <Slider
          label="Volume"
          defaultValue={5}
          disabled={disabled()}
          onReady={(slider) => {
            api = slider;
          }}
        />
      ),
      root,
    );
    const partOf = (name: string) => root.querySelector<HTMLElement>(`[data-part="${name}"]`)!;
    return {
      setDisabled,
      api: () => api,
      thumb: () => partOf("slider-thumb"),
      rail: () => partOf("slider"),
      dispose: () => {
        dispose();
        root.remove();
      },
    };
  };

  it("keeps its tab stop, announces aria-disabled and ignores a key and a rail press", async () => {
    const { setDisabled, api, thumb, rail, dispose } = renderSlider();
    const now = () => thumb().getAttribute("aria-valuenow");
    expect(thumb().getAttribute("aria-disabled")).toBe("true");
    // the thumb is the pattern's tab stop either way
    expect(thumb().getAttribute("tabindex")).toBe("0");

    thumb().focus();
    await tick();
    expect(api()?.focused()).toBe(true);
    thumb().dispatchEvent(new KeyboardEvent("keydown", { key: "ArrowRight", bubbles: true }));
    await tick();
    expect(now()).toBe("5");

    const rect = rail().getBoundingClientRect();
    rail().dispatchEvent(
      new PointerEvent("pointerdown", { bubbles: true, clientX: rect.left + rect.width * 0.8 }),
    );
    await tick();
    rail().dispatchEvent(
      new PointerEvent("pointermove", { bubbles: true, clientX: rect.left + rect.width }),
    );
    await tick();
    expect(now()).toBe("5");

    // the getter is live: enabling the thumb enables its keys and its rail
    setDisabled(false);
    await tick();
    expect(thumb().hasAttribute("aria-disabled")).toBe(false);
    thumb().dispatchEvent(new KeyboardEvent("keydown", { key: "ArrowRight", bubbles: true }));
    await tick();
    expect(now()).toBe("6");
    rail().dispatchEvent(
      new PointerEvent("pointerdown", { bubbles: true, clientX: rect.left + rect.width * 0.8 }),
    );
    await tick();
    expect(now()).toBe("8");
    dispose();
  });
});

// The drag is a deliberate extension of `specs/apg/slider.qnt` (which fixes a
// discrete rail press and has no pointer position), so these cases are its
// oracle: the pointer's position on the rail is the value, in every
// orientation / direction, and a controlled host still owns the outcome.
describe("Slider drag", () => {
  const mountDrag = (options: SliderOptions) => {
    const root = document.createElement("div");
    root.style.cssText =
      options.orientation === "vertical"
        ? "position:fixed;top:0;left:0;width:100px;height:100px"
        : "position:fixed;top:0;left:0;width:100px;height:20px";
    document.body.append(root);
    const requests: number[] = [];
    let api: SliderController | undefined;
    const dispose = render(
      () => (
        <Slider
          label="Volume"
          {...options}
          onReady={(slider) => {
            api = slider;
          }}
          onValueChange={(value) => {
            requests.push(value);
            options.onValueChange?.(value);
          }}
        />
      ),
      root,
    );
    const partOf = (name: string) => root.querySelector<HTMLElement>(`[data-part="${name}"]`)!;
    return {
      requests,
      rail: () => partOf("slider"),
      thumb: () => partOf("slider-thumb"),
      now: () => partOf("slider-thumb").getAttribute("aria-valuenow"),
      focused: () => api?.focused() === true,
      dispose: () => {
        dispose();
        root.remove();
      },
    };
  };

  // The rail is the skin's box (a 100x8 strip, or 8x40 upright), so a pointer is
  // placed as a fraction of the rail's rect rather than at the primitive test's
  // pixels; a move dispatched on the thumb is read against the rail, as the
  // primitive reads it.
  const pointer = (
    rail: () => HTMLElement,
    element: Element,
    type: string,
    x: number,
    y: number,
  ): void => {
    const rect = rail().getBoundingClientRect();
    element.dispatchEvent(
      new PointerEvent(type, {
        bubbles: true,
        clientX: rect.left + rect.width * x,
        clientY: rect.top + rect.height * y,
      }),
    );
  };

  it("follows the pointer along the rail, one request per value, and stops on release", async () => {
    const slider = mountDrag({ defaultValue: 0 });
    // a secondary click is not a press
    slider
      .rail()
      .dispatchEvent(
        new PointerEvent("pointerdown", { bubbles: true, button: 2, clientX: 90, clientY: 4 }),
      );
    await tick();
    expect(slider.now()).toBe("0");

    pointer(slider.rail, slider.rail(), "pointerdown", 0, 0.5);
    await tick();
    expect(slider.now()).toBe("0");
    // a press at the value it already has is no request
    expect(slider.requests).toEqual([]);
    expect(slider.focused()).toBe(true);

    // 0.24 -> 2; then three moves inside one step, which is one request
    for (const x of [0.24, 0.51, 0.5, 0.52]) {
      pointer(slider.rail, slider.rail(), "pointermove", x, 0.5);
      await tick();
    }
    expect(slider.now()).toBe("5");
    expect(slider.requests).toEqual([2, 5]);

    pointer(slider.rail, slider.rail(), "pointerup", 0.52, 0.5);
    await tick();
    pointer(slider.rail, slider.rail(), "pointermove", 0.9, 0.5);
    await tick();
    expect(slider.now()).toBe("5");
    slider.dispose();
  });

  it("clamps a drag past either end", async () => {
    const slider = mountDrag({ defaultValue: 5 });
    pointer(slider.rail, slider.rail(), "pointerdown", 0.5, 0.5);
    await tick();
    expect(slider.now()).toBe("5");
    pointer(slider.rail, slider.rail(), "pointermove", -0.4, 0.5);
    await tick();
    expect(slider.now()).toBe("0");
    pointer(slider.rail, slider.rail(), "pointermove", 1.4, 0.5);
    await tick();
    expect(slider.now()).toBe("10");
    pointer(slider.rail, slider.rail(), "pointerup", 1.4, 0.5);
    await tick();
    expect(slider.requests).toEqual([0, 10]);
    slider.dispose();
  });

  it("a vertical rail increases upward, ltr and rtl alike", async () => {
    for (const direction of ["ltr", "rtl"] as const) {
      const slider = mountDrag({ orientation: "vertical", direction, defaultValue: 0 });
      pointer(slider.rail, slider.rail(), "pointerdown", 0.5, 0.99);
      await tick();
      expect(slider.now()).toBe("0");
      pointer(slider.rail, slider.rail(), "pointermove", 0.5, 0.2);
      await tick();
      expect(slider.now()).toBe("8");
      pointer(slider.rail, slider.rail(), "pointermove", 0.5, 0.79);
      await tick();
      expect(slider.now()).toBe("2");
      pointer(slider.rail, slider.rail(), "pointerup", 0.5, 0.79);
      await tick();
      slider.dispose();
    }
  });

  it("a horizontal rtl rail counts from the right", async () => {
    const slider = mountDrag({ direction: "rtl", defaultValue: 5 });
    pointer(slider.rail, slider.rail(), "pointerdown", 0, 0.5);
    await tick();
    expect(slider.now()).toBe("10");
    pointer(slider.rail, slider.rail(), "pointermove", 1, 0.5);
    await tick();
    expect(slider.now()).toBe("0");
    pointer(slider.rail, slider.rail(), "pointerup", 1, 0.5);
    await tick();
    slider.dispose();
  });

  it("a press on the thumb starts the drag where the value is", async () => {
    const slider = mountDrag({ defaultValue: 5 });
    // off the thumb's centre: it is already at its value, so no jump
    pointer(slider.rail, slider.thumb(), "pointerdown", 0.54, 0.5);
    await tick();
    expect(slider.now()).toBe("5");
    expect(slider.requests).toEqual([]);
    // a captured move is retargeted to the rail; here it bubbles to it
    pointer(slider.rail, slider.thumb(), "pointermove", 0.8, 0.5);
    await tick();
    expect(slider.now()).toBe("8");
    pointer(slider.rail, slider.thumb(), "pointerup", 0.8, 0.5);
    await tick();
    slider.dispose();
  });

  it("a controlled host that rejects the drag keeps its value", async () => {
    // `value` without an accepting host: every request is ignored
    const slider = mountDrag({ value: 5, defaultValue: 5 });
    pointer(slider.rail, slider.rail(), "pointerdown", 0.1, 0.5);
    await tick();
    pointer(slider.rail, slider.rail(), "pointermove", 0.9, 0.5);
    await tick();
    expect(slider.now()).toBe("5");
    expect(slider.requests).toEqual([1, 9]);
    pointer(slider.rail, slider.rail(), "pointerup", 0.9, 0.5);
    await tick();
    slider.dispose();
  });

  it("a lost capture and a cancel both end the drag", async () => {
    const slider = mountDrag({ defaultValue: 0 });
    pointer(slider.rail, slider.rail(), "pointerdown", 0.2, 0.5);
    await tick();
    expect(slider.now()).toBe("2");

    slider.rail().dispatchEvent(new PointerEvent("lostpointercapture", { bubbles: true }));
    await tick();
    pointer(slider.rail, slider.rail(), "pointermove", 1, 0.5);
    await tick();
    expect(slider.now()).toBe("2");

    pointer(slider.rail, slider.rail(), "pointerdown", 0.2, 0.5);
    await tick();
    expect(slider.now()).toBe("2");
    pointer(slider.rail, slider.rail(), "pointermove", 0.3, 0.5);
    await tick();
    expect(slider.now()).toBe("3");
    slider.rail().dispatchEvent(new PointerEvent("pointercancel", { bubbles: true }));
    await tick();
    pointer(slider.rail, slider.rail(), "pointermove", 0.9, 0.5);
    await tick();
    expect(slider.now()).toBe("3");
    slider.dispose();
  });
});

import solid from "@solidjs/vite-plugin";
import cssints, { targets } from "cssints/vite";
import { defineConfig } from "vite-plus";
import { playwright } from "vite-plus/test/browser-playwright";

// The conformance test a starter arrives with runs in a real Chromium: the scenario walk needs a
// real DOM and Solid 2's reactivity, not a simulated one.
export default defineConfig({
  // `evaluation.inline`: a browser-mode runner inlines everything as ESM, so the plugin's own
  // evaluation server keeps the framework's packages inlined (Solid resolves its client build by
  // them) and the rest external (Node loads their CJS). Without it, a click's target resolves
  // against a second copy of Solid and the walk reads a state the page never changed.
  plugins: [
    cssints({ evaluation: { inline: ["solid-js", "@solidjs/web", "@solidjs/signals"] } }),
    solid(),
  ],
  css: { transformer: "lightningcss", lightningcss: { targets } },
  // The plugin adds `import derived from "cssints/derived"` to a client module after the dep
  // scanner has run; pre-bundling it here is what keeps that from reloading the page mid-test.
  optimizeDeps: { include: ["cssints/derived"] },
  test: {
    // a browser test has no app entry: the sheet of the modules the test imports arrives through
    // `virtual:cssints.css`, and vitest drops CSS imports unless it is told to process them
    css: true,
    // the sheet is loaded by the test's imports, not before them
    setupFiles: ["src/sheet.ts"],
    include: ["src/components/ui/**/*.browser.test.tsx"],
    browser: {
      enabled: true,
      provider: playwright(),
      headless: true,
      viewport: { width: 1280, height: 1024 },
      instances: [{ browser: "chromium" }],
      // The default waits 60 s for a worker's iframe to come up, which a busy machine (or a CI runner with a dozen other
      // jobs) misses: the run then fails as `the iframe did not become ready` with no test having run. Nothing about a
      // test gets longer; this is the browser starting.
      connectTimeout: 120_000,
      // the iframe ready timeout is read from the config's own env, not from the process that started the run
      env: { VITEST_BROWSER_IFRAME_TIMEOUT: "120000" },
    },
  },
});

// The engine's sheet for a browser test: its content is the CSS of the modules transformed so far, so it is loaded once the
// test file's imports are in (in `beforeAll`, not as a static import: vitest resolves the graph as it goes, and a sheet loaded
// first is just the `@layer` statement). A component's conformance test clicks its parts, so the sheet has to be there.
import { beforeAll } from "vite-plus/test";

beforeAll(async () => {
  await import("virtual:cssints.css");
});
